// D-2..D-1 as plain YYYY-MM-DD (UTC), matching platform-nest's own addDaysIso/todayIso convention.
function addDays(iso, n) {
  const d = new Date(`${iso}T00:00:00.000Z`);
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}
const today = new Date().toISOString().slice(0, 10);
return [{ json: { from: addDays(today, -2), to: addDays(today, -1) } }];

// Success: nothing to notify -- a clean recompute is silent, same posture as every other
// clear-on-success flow in this repo (compliance-gate-nag/stale-approval-chaser).
const body = $input.first().json.body ?? $input.first().json;
return [{ json: { ok: true, jobRunId: body.jobRunId ?? null, days: body.days ?? null } }];

// Dead-letter payload for the error branch -- retries (x3) already exhausted at this point.
const err = $input.first().json.error ?? $input.first().json;
return [{ json: { from: $('Compute D-2..D-1').first().json.from, to: $('Compute D-2..D-1').first().json.to, error: String(err?.message ?? err) } }];
